function showPolicy() {
  const existing=snapshot.workspace?.policies?.[creditYear];
  openDialog('Approve clinical credit rules · '+creditYear,`<p>The annual workbook formula is Weeks = G20 + H22 + Weekday Nights + Akron + Consults, and Weekends = Main Weekends + Weekend Nights + Akron Weekends. Source: Staff ${creditYear} #s, columns B–K.</p><p class="wb-notice">Select only confirmed rules. Each chosen source date earns 1 ÷ days-per-credit, allocated by approved participant shares. This explicitly permits partial credit and clips dates to the selected calendar year. The workbook does not establish this conversion by itself. Night weekdays must be chosen explicitly. Rules apply to unannotated single-person source assignments as ordinary scheduled work; moonlighting remains separately identified.</p><form id="wb-policy-form"><div class="wb-scroll"><table class="wb-table"><thead><tr><th>Approve category</th><th>Qualifying source weekdays</th><th>Dates per credit unit</th><th>Moonlighting reduces obligation</th></tr></thead><tbody>${creditCategories.map(c=>{const rule=existing?.rules.find(r=>r.category===c.id);return `<tr><th><label><input type="checkbox" name="rule" value="${c.id}" ${rule?'checked':''}>${escape(c.label)} (${c.unit})</label></th><td><div class="wb-day-options">${weekdays.map((d,index)=>`<label><input type="checkbox" name="days-${c.id}" value="${index}" ${(rule?.days??c.days).includes(index)?'checked':''}>${d}</label>`).join('')}</div></td><td><input type="number" aria-label="Dates per ${c.label} credit" name="rate-${c.id}" min="0.000001" max="31" step="any" value="${escape(rule?.daysPerCredit??'')}"></td><td><input type="checkbox" aria-label="Moonlighting counts for ${c.label}" name="moon-${c.id}" ${rule?.moonlightingCredit?'checked':''}></td></tr>`;}).join('')}</tbody></table></div><label>Rule rationale / clinical approval<textarea name="note" required maxlength="2000">${escape(existing?.note??'')}</textarea></label><label class="wb-group-choice"><input type="checkbox" name="confirm" required><span>I approve these day sets, partial-credit rates, calendar-year scope and moonlighting treatment. Unselected categories remain unvalued.</span></label><p class="wb-error" role="alert"></p><button class="primary">Save approved credit rules</button></form>`);
  const fte=snapshot.workbook.sheets.find(s=>s.name==='FTE Calc');
  if(fte){$('#wb-policy-form').insertAdjacentHTML('beforebegin',`<details><summary>Inspect conflicting workbook night conversions</summary><p>The 2027 demand model uses 3 weekday-night and 4 weekend-night dates per block. The per-person breakdown implies 5 and 2. Neither establishes a confirmed rule for ${creditYear}, or specifies the exact weekday sets.</p>${sourceTable(fte.cells.filter(c=>['A8','B8','E8','H8','A9','B9','E9','H9','A19','B19','C19','A20','B20','C20'].includes(c.address)).map(c=>c.id))}</details>`);bindSources();}
  $('#wb-policy-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form);const input={year:creditYear,note:f.get('note'),rules:f.getAll('rule').map(category=>({category,days:f.getAll('days-'+category).map(Number),daysPerCredit:Number(f.get('rate-'+category)),moonlightingCredit:f.has('moon-'+category)}))};const button=form.querySelector('button');button.disabled=true;try{await workspaceSave('policy',input);$('#wb-dialog').close();}catch(error){form.querySelector('[role="alert"]').textContent=error.message;}finally{button.disabled=false;}};
}
function renderAssistant() {
  let results=assistantResults;
  if(results===null&&selectedCandidate){try{results=candidates(snapshot,proposal);}catch{results=[];}}
  const chosen=results?.find(c=>c.staffId===selectedCandidate),drafts=Object.values(snapshot.workspace?.drafts??{});
  $('#wb-content').innerHTML=`<div class="wb-section-title"><div><h2>Scheduling assistance</h2><p>Compare replacements or propose coverage for a selected date. Blank source cells are not automatically treated as required gaps.</p></div><button id="wb-profile">Confirm staff eligibility / active dates</button></div><p class="wb-notice">Select a comparison category to rank by workbook-reported shortfall while conversions are pending, or by partial valued credit when approvals exist. No source and derived totals are added together. Ranking is partial while credit or availability is unresolved. Confirmed leave, inactive dates, ineligible services and duplicate same-service assignments block saving. Missing times, rest rules and compatibility checks require explicit review.</p><form id="wb-proposal" class="wb-controls"><label>Date<input name="date" type="date" required value="${escape(proposal.date)}" ${proposal.sourceId?'readonly':''}></label><label>Clinical service<select name="service" ${proposal.sourceId?'disabled':''}>${clinicalServices.map(s=>option(s,s,proposal.service===s)).join('')}</select></label><label>Time window<select name="period">${periods.map(p=>option(p,p,proposal.period===p)).join('')}</select></label><label>Classification<select name="classification">${option('unspecified','Ordinary / unannotated source',proposal.classification==='unspecified')+option('moonlighting','Moonlighting',proposal.classification==='moonlighting')}</select></label><label>Credit category (comparison only)<select name="comparisonCategory">${option('','Unspecified')+creditCategories.filter(c=>c.service===proposal.service).map(c=>option(c.id,c.label,proposal.comparisonCategory===c.id)).join('')}</select></label><button class="primary">Compare candidates</button>${proposal.sourceId||proposal.id?'<button type="button" id="wb-new-proposal">Start a new proposal</button>':''}</form>${proposal.sourceId?`<p>Replacing source ${escape(view.records.find(r=>r.id===proposal.sourceId)?.sheet)}!${escape(view.records.find(r=>r.id===proposal.sourceId)?.address)}. The source is retained.</p>`:''}<p id="wb-assistant-error" class="wb-error" role="alert"></p>${results?`<div class="wb-scroll"><table class="wb-table" id="wb-candidates"><thead><tr><th>Candidate</th><th>Remaining obligation (partial)</th><th>Proposed credit</th><th>Findings</th><th>Select</th></tr></thead><tbody>${results.map(c=>`<tr><th>${escape(c.name)}</th><td>${quantity(c.remaining)} ${escape(c.unit??'')}<small>${escape(c.remainingBasis)}</small></td><td>${quantity(c.impact)} ${escape(c.unit??'')}</td><td>${c.blocked.length?`<strong class="wb-error">Blocked: ${c.blocked.map(escape).join(' ')}</strong>`:'Requires review'}<details><summary>${c.warnings.length} incomplete checks</summary><ul>${c.warnings.map(w=>`<li>${escape(w)}</li>`).join('')}</ul></details></td><td><button data-candidate="${c.staffId}" ${c.blocked.length?'disabled':''}>${selectedCandidate===c.staffId?'Selected':'Review candidate'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p>Choose the date and activity, then compare candidates.</p>'}${chosen&&!chosen.blocked.length?`<form id="wb-draft-form" class="wb-draft-form"><h3>Draft assignment: ${escape(chosen.name)}</h3><ul>${chosen.warnings.map(w=>`<li>${escape(w)}</li>`).join('')}</ul><label>Decision / override reason<textarea name="note" required maxlength="2000"></textarea></label><label class="wb-group-choice"><input name="acknowledge" type="checkbox" required><span>I reviewed these incomplete checks and accept this as a provisional draft assignment.</span></label><button class="primary">Save draft assignment</button><p class="wb-error" role="alert"></p></form>`:''}<h3>App drafts (${drafts.length})</h3>${drafts.map(d=>`<button class="wb-issue-link" data-draft="${d.id}">${escape(d.date+' · '+d.service+' · '+view.staff.find(p=>p.id===d.staffId)?.name)}<small>${d.sourceId?'Replaces source entry':'New proposed assignment'} · inspect or remove</small></button>`).join('')||'<p>No app drafts saved.</p>'}`;
  $('#wb-profile').onclick=showProfile;
  const proposalForm=$('#wb-proposal');
  proposalForm.oninput=()=>{selectedCandidate='';if($('#wb-draft-form'))$('#wb-draft-form').remove();};
  proposalForm.elements.namedItem('service').onchange=e=>{proposalForm.elements.namedItem('comparisonCategory').innerHTML=option('','Unspecified')+creditCategories.filter(c=>c.service===e.target.value).map(c=>option(c.id,c.label)).join('');};
  proposalForm.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);proposal={...proposal,date:f.get('date'),service:proposal.sourceId?proposal.service:f.get('service'),period:f.get('period'),classification:f.get('classification'),comparisonCategory:f.get('comparisonCategory')};selectedCandidate='';try{assistantResults=candidates(snapshot,proposal);renderAssistant();}catch(error){$('#wb-assistant-error').textContent=error.message;}};
  if($('#wb-new-proposal'))$('#wb-new-proposal').onclick=()=>{proposal={date:today,service:'G20',period:'day',classification:'unspecified'};selectedCandidate='';assistantResults=null;renderAssistant();};
  document.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>{selectedCandidate=b.dataset.candidate;renderAssistant();$('#wb-draft-form')?.scrollIntoView({block:'center'});});
  document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>showRecord(b.dataset.draft));
  if($('#wb-draft-form'))$('#wb-draft-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),button=form.querySelector('button');button.disabled=true;try{await workspaceSave('draft',{...proposal,staffId:selectedCandidate,note:f.get('note'),acknowledgeWarnings:f.has('acknowledge')});selectedCandidate='';assistantResults=null;proposal={date:proposal.date,service:proposal.service,period:proposal.period,classification:proposal.classification};renderAssistant();message('Draft saved. Schedule and clinical credits now reflect the same assignment.');}catch(error){form.querySelector('[role="alert"]').textContent=error.message;}finally{button.disabled=false;}};
}
function showProfile(id) {
  const person=view.staff.find(p=>p.id===id)??view.staff[0],profile=snapshot.workspace?.profiles?.[person.id];
  openDialog('Confirm staff scheduling eligibility',`<p>Annual targets and future scenario staff do not establish clinical eligibility. Confirm the person's active interval and eligible services. A no-nights obligation note does not alone prohibit voluntary moonlighting.</p><form id="wb-profile-form"><label>Person<select name="staffId">${view.staff.map(p=>option(p.id,p.name,p.id===person.id)).join('')}</select></label><div class="wb-controls"><label>Active from<input type="date" name="from" required value="${escape(profile?.from??'2026-01-01')}"></label><label>Active through<input type="date" name="to" required value="${escape(profile?.to??'2026-12-31')}"></label></div><fieldset><legend>Confirmed eligible services</legend><div class="wb-person-options">${clinicalServices.map(s=>`<label><input name="services" type="checkbox" value="${s}" ${profile?.services.includes(s)?'checked':''}>${s}</label>`).join('')}</div></fieldset><label>Clinical eligibility confirmation / reason<textarea name="note" required maxlength="2000">${escape(profile?.note??'')}</textarea></label><p class="wb-error" role="alert"></p><button class="primary">Save eligibility profile</button></form>`);
  const form=$('#wb-profile-form');form.elements.namedItem('staffId').onchange=e=>showProfile(e.target.value);
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),button=form.querySelector('button');button.disabled=true;try{await workspaceSave('profile',{staffId:f.get('staffId'),from:f.get('from'),to:f.get('to'),services:f.getAll('services'),note:f.get('note')});$('#wb-dialog').close();}catch(error){form.querySelector('[role="alert"]').textContent=error.message;}finally{button.disabled=false;}};
}
try {await history();if(imports.length)accept(await api(`/api/imports/${imports[0].id}`),true);}
catch(error){message(`Unable to load saved workbooks: ${error.message} Start the app with npm start and use its local address.`,true);}
